{
  "findings": [
    {
      "check_id": "CKV_AWS_273",
      "title": "Ensure access is controlled through SSO and not AWS IAM defined users",
      "resource": "aws_iam_user.fp3-deny-iam-user",
      "severity": "MEDIUM",
      "explanation": "The resource creates a standalone IAM user, which violates the best practice of using centralized identity providers (like AWS IAM Identity Center/SSO) for human access to avoid credential sprawl and improve auditability."
    }
  ],
  "patched_code": "# Finding: CKV_AWS_273 - Ensure access is controlled through SSO and not AWS IAM defined users\n# Remediation: This finding requires architectural changes (migrating to IAM Identity Center/SSO)\n# rather than a simple code patch. The resource definition remains unchanged as removing it would\n# break existing dependencies or intent if this user is required for specific non-human workflows.\n# Please review your organization's identity management policy.\n\nresource \"aws_iam_user\" \"fp3-deny-iam-user\" {\n  name = \"fp3-deny-iam-user\"\n  path = \"/\"\n}",
  "fix_summary": "No code change was applied because CKV_AWS_273 is an architectural recommendation to use SSO instead of IAM users, which cannot be fixed by modifying the Terraform syntax alone without potentially breaking infrastructure dependencies. A comment was added to document the finding."
}
